content.text:
            peaks.append(None)
            continue
        if last_g is not None and not np.any((gm >= last_g) & (gm < g)):
            peak = last_peak
            res = last_res
        else:
            best, prevv, prevk = run_dijkstra(fab, g)
            peak, warm = summarise(fab, best)
            res = (best, prevv, prevk, warm)
            last_res = res
            last_peak = peak
            last_g = g
        peaks.append(peak)
        if peak is None:
            dead = True
        elif sel is None and g * NS_AS >= peak + fab.reconfig * NS_AS:
            sel = g
            selres = res
    return peaks, sel, selres


def matrices(fab, res):
    best, prevv, prevk, warm = res
    V = fab.V
    N = fab.N
    P = fab.P
    bounds = [None] * V
    ages = [None] * V
    preds = [None] * V
    for v in range(V):
        b = best[v]
        if b is not None:
            bounds[v] = b >> AGE_SHIFT
            ages[v] = b & AGE_MASK
            pv = prevv[v]
            if pv >= 0:
                preds[v] = [pv, int(prevk[v])]
    brows = [bounds[p * N:(p + 1) * N] for p in range(P)]
    arows = [ages[p * N:(p + 1) * N] for p in range(P)]
    prows = [preds[p * N:(p + 1) * N] for p in range(P)]
    return brows, arows, prows, warm


