def _flatten(mat, P, N):
    """Flatten a P x N matrix of integer-or-null cells; None if malformed."""
    if not isinstance(mat, list) or len(mat) != P:
        return None
    out = []
    for row in mat:
        if not isinstance(row, list) or len(row) != N:
            return None
        for x in row:
            if x is not None and not is_int(x):
                return None
        out.extend(row)
    return out


def check_calib_cert(cal, prop):
    K = cal.K
    if not isinstance(prop, dict) or set(prop.keys()) != CAL_KEYS:
        return False
    if prop['status'] != 'ok':
        return False
    up = prop['upper_ps']
    pr = prop['pred']
    if not isinstance(up, list) or len(up) != K:
        return False
    if not isinstance(pr, list) or len(pr) != K:
        return False
    two_m = 2 * cal.M
    heads = cal.heads
    tails = cal.tails
    wts = cal.weights
    truth = cal.upper
    for a in range(K):
        ra = up[a]
        pa = pr[a]
        if not isinstance(ra, list) or len(ra) != K:
            return False
        if not isinstance(pa, list) or len(pa) != K:
            return False
        ta = truth[a]
        for b in range(K):
            x = ra[b]
            if not is_int(x) or x != ta[b]:
                return False
        if pa[a] is not None:
            return False
        sums = [None] * K
        state = bytearray(K)
        state[a] = 2
        sums[a] = 0
        for b in range(K):
            if b == a:
                continue
            stack = []
            cur = b
            ok = False
            base = 0
            while True:
                st = state[cur]
                if st == 2:
                    base = sums[cur]
                    ok = True
                    break
                if st == 1:
                    break
                e = pa[cur]
                if not is_int(e) or e < 0 or e >= two_m:
                    break
                if heads[e] != cur:
                    break
                state[cur] = 1
